 function resolve(){const issue=api.issue;if(!issue)return;if(issue.legacy){showSheet('이전 버전 대기 입력',body=>{const p=document.createElement('p');p.className='conflict';p.textContent=issue.message+'\n기존 대기 입력은 기기에 보관되어 있습니다.';body.append(p);const commands=root.legacy.filter(c=>c.date===issue.date);const pre=document.createElement('pre');pre.className='notion-preview';pre.textContent=commands.map(c=>c.op+' '+time(c.first)+'–'+time(c.last+1)).join('\n');body.append(pre);if(issue.pc)body.append(button('최신 PC 상태에 첫 입력 적용',async()=>{const c=commands[0];try{await request('/api/command','POST',{...c,baseRevision:issue.pc.view.revision});root.legacy=root.legacy.filter(x=>x.requestId!==c.requestId);api.issue=null;save();closeSheet();sync()}catch(error){toast(error.message)}},'wide secondary'),button('대기 입력 보관 후 PC 기록 사용',()=>{root.backups.push({at:Date.now(),date:issue.date,phone:E.clone(entry(issue.date).local),pc:issue.pc.state,pending:E.clone(commands)});root.backups=root.backups.slice(-16);root.legacy=root.legacy.filter(c=>c.date!==issue.date);api.issue=null;save();closeSheet();sync()},'wide secondary'));body.append(button('나중에',closeSheet,'wide secondary'))});return;}showSheet('양쪽 변경 확인',body=>{const text=document.createElement('p');text.className='conflict';text.textContent=issue.message;body.append(text);const info=document.createElement('p');info.className='form-note';info.textContent='서로 다른 시간의 기록은 자동으로 합칩니다. 겹친 변경은 자동으로 덮어쓰지 않습니다. 아래 선택은 '+(issue.date||'해당')+' 날짜에 적용하며, 선택 전 두 기록을 보관합니다.';body.append(info);if(!issue.pc)return;const e=entry(issue.date);for(const [label,view] of [['휴대폰',E.snapshot(e.local,issue.date)],['PC',issue.pc.view]]){if(!view)continue;const pre=document.createElement('pre');pre.className='notion-preview';pre.textContent=label+' · '+issue.date+'\n'+view.actual.map(b=>time(b.start)+'–'+time(b.start+b.count)+' '+(b.name||b.category)+' · 집중 '+b.score+' / 만족 '+b.satisfaction).join('\n');body.append(pre)}body.append(button('PC 내용 사용 · 휴대폰 내용 보관',()=>{keepConflict(e,issue);const state=E.decode(JSON.parse(issue.pc.state));e.local=state;e.base=E.clone(state);e.dirty=false;e.serial++;e.undo=[];api.issue=null;save();closeSheet();show(A.date);sync()},'wide secondary'));body.append(button('휴대폰 내용 사용 · PC 내용 보관',async()=>{keepConflict(e,issue);try{await fetchDate(issue.date,true);api.issue=null;closeSheet();show(A.date);sync()}catch(error){issue.message=error.message;try{issue.pc=await request('/api/replica?date='+issue.date);issue.revision=issue.pc.revision}catch{}resolve()}},'wide secondary'))})}
 return api;
