function adherenceSheet(){showSheet('이행도 · 9점 만점',root=>{const note=document.createElement('p');note.className='form-note';note.textContent='시작·종료 오차 10분마다 1점 차감 · 최저 0점\n식사는 시작만, 준비·기상·기록 없는 계획은 평가 제외\n행동별 동일 비중 · 실제 기록으로 일정이 바뀌기 전 계획과 비교';root.append(note);let actions=[];try{actions=JSON.parse(A.view?.adherenceDetails||'[]')}catch{}if(!actions.length){const empty=document.createElement('p');empty.className='form-note';empty.textContent='비교 기준이 저장된 행동 기록이 아직 없습니다. 기존 기록은 당시 계획을 확인할 수 없어 미평가일 수 있습니다.';root.append(empty)}for(const a of actions){const item=document.createElement('div');item.className='adherence-action';const delta=m=>(m>0?'+':'')+m+'분';item.textContent=(a.name||categoryLabel(a.category))+' · '+Number(a.score).toFixed(1).replace(/\.0$/,'')+'/9\n시작 '+time(a.planned_start/10)+' → '+time(a.actual_start/10)+' ('+delta(a.start_error_minutes)+')'+(a.end_score==null?'': '\n종료 '+time(a.planned_end/10)+' → '+time(a.actual_end/10)+' ('+delta(a.end_error_minutes)+')');item.style.whiteSpace='pre-line';root.append(item)}})}
$('adherenceCard').onclick=adherenceSheet;$('adherenceCard').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();adherenceSheet()}};
function categorySettingsSheet(){if(!A.view)return;showSheet('카테고리 관리',root=>{const note=document.createElement('p');note.className='form-note';note.textContent='이 기기에 먼저 저장하고 연결되면 동기화합니다. 삭제해도 과거 기록은 유지됩니다.';root.append(note);const settings=A.view.categorySettings?.filter(c=>!c.deleted)||A.view.categories.map(name=>({name,label:name,color:'#59836d',hidden:false}));settings.forEach((item,index)=>{const b=categoryButton(item.name,()=>categoryEditSheet(item,index));b.className+=' wide secondary';if(item.hidden)b.children[1].textContent+=' · 숨김';root.append(b)});root.append(button('새 카테고리',()=>categoryEditSheet(null,settings.length)))})}
