 const newForm=document.createElement('div');newForm.hidden=true;const[newLabel,newTitle]=input('새 페이지 이름','text');newTitle.maxLength=80;const placement=document.createElement('select');placement.className='form-input';placement.setAttribute('aria-label','새 페이지 위치');for(const[value,label]of[['private','개인 공간 맨 위'],['selected','선택한 페이지 아래']]){const option=document.createElement('option');option.value=value;option.textContent=label;placement.append(option)}placement.value='private';newForm.append(newLabel,placement);const createPage=button('페이지 생성 후 선택',()=>run(async()=>{const title=newTitle.value.trim();if(!title||title.length>80)throw Error('새 페이지 이름을 1~80자로 입력해 주세요');const parent=placement.value==='selected'?hubId(url.value):null;if(parent){const v=hubDecode(await call('fetch',{id:parent})),text=v.text||'';if(['database','data_source'].includes(v.metadata?.type)||!/<page\b/.test(text)&&/<database\b|<data-source\b/.test(text))throw Error('일반 페이지를 먼저 선택해 주세요')}const key='ara.notion.newpage.'+(config.workspace||'')+'.'+(parent||'private')+'.'+title;if(saved(key,null)?.status==='requested')throw Error('이 페이지의 생성 결과를 목록에서 먼저 확인해 주세요. 중복 요청을 막았습니다.');persist(key,{status:'requested',at:Date.now()});let result;try{result=await call('create-pages',{...(parent?{parent:{page_id:parent}}:{creation_mode:'draft'}),allow_async:false,pages:[{properties:{title}}]});const row=hubCreatedRow(result,title);persist(key,{status:'created',row});await choose(row);newTitle.value='';newForm.hidden=true;toast(parent?'선택한 페이지 아래에 만들고 선택했습니다':'개인 공간에 새 페이지를 만들고 선택했습니다')}catch(e){throw Error(e.message+'\n생성 결과가 불확실하면 페이지 목록을 새로고침해 확인해 주세요.')}}),'wide secondary');buttons.push(createPage);newForm.append(createPage);const newPageButton=add('새 페이지 만들기',async()=>{newForm.hidden=!newForm.hidden});root.append(newForm);quickCreate.append(newPageButton,newForm);
