 const summary=document.createElement('p');summary.className='form-note';try{const d=notionDaySummary();summary.textContent=`저장할 날: ${d.date} (기상일) · 기록 ${d.minutes}분\n집중 ${d.focusAverage}/5 · 만족도 ${d.satisfactionAverage}/5 · 집중 총점 ${d.focusTotal}`;}catch{}dailyArea.append(summary);
