function notionDraftKey(){return 'ara.diary.'+A.date}
async function notionCall(input){return request('/api/notion','POST',{date:A.date,...input})}
function notionSheet(){if(E&&R&&(!A.online||R.pending())){showSheet('노션 · AI 하루 정리',root=>{const note=document.createElement('p');note.className='form-note';note.textContent='이 기기에 저장된 기록을 PC와 동기화한 뒤 노션·PC AI를 사용해 주세요. 오프라인 기록은 그대로 보관됩니다.';root.append(note,button('기록 먼저 동기화',async()=>{await R.sync();if(A.online&&!R.pending())notionSheet()},'wide secondary'))});return}
 showSheet('노션 · AI 하루 정리',root=>{
  const state=document.createElement('p');state.className='form-note';state.textContent='연결 상태 확인 중';root.append(state);
  const [queryLabel,query]=input('페이지 검색','text');root.append(queryLabel);
  const list=document.createElement('div');list.className='category-grid';
  const [urlLabel,url]=input('노션 링크 또는 ID','text');const kind=document.createElement('select');kind.className='form-input';kind.setAttribute('aria-label','노션 위치 종류');for(const [value,label] of [['page','페이지'],['data_source','데이터 원본'],['database','데이터베이스']]){const option=document.createElement('option');option.value=value;option.textContent=label;kind.append(option)}
  const preview=document.createElement('pre');preview.className='notion-preview';preview.textContent='기상일 '+A.date+' 기준으로 저장합니다. 실제 기록·집중·만족도·메모·과제가 포함됩니다.';
  const draft=document.createElement('textarea');draft.className='form-input';draft.rows=7;draft.maxLength=30000;draft.setAttribute('aria-label','확인하고 수정할 일기 초안');draft.value=saved(notionDraftKey(),'');draft.oninput=()=>persist(notionDraftKey(),draft.value);
  let working=false,config=null;const buttons=[];
  const run=async action=>{if(working)return;working=true;buttons.forEach(b=>b.disabled=true);try{await action()}catch(e){toast(e.message);state.textContent=e.message}finally{working=false;buttons.forEach(b=>b.disabled=false)}};
  const add=(text,action)=>{const b=button(text,()=>run(action),'wide secondary');buttons.push(b);root.append(b);return b};
  const showStatus=value=>{config=value;state.textContent=(value.connected?'노션 연결됨':'PC 앱의 노션 · AI에서 먼저 연결해 주세요')+'\n저장: '+(value.target?.title||'미지정')+'\n참고: '+(value.reference?.title||'미지정')+'\nAI: '+(value.model?'PC 로컬 · '+value.model:'로컬 모델 미설정 · 일기 직접 입력 가능')};
  add('페이지 검색',async()=>{const result=await notionCall({op:'search',text:query.value});list.replaceChildren();for(const item of result.results){const b=button(item.title+' · '+(item.kind==='page'?'페이지':'데이터 원본'),()=>{url.value=item.id;kind.value=item.kind;toast('위치를 골랐습니다. 저장 위치 또는 참고 위치로 지정하세요')},'');list.append(b)}if(!result.results.length)list.textContent='결과 없음 · 노션에서 ARA 연결에 접근을 허용했는지 확인하세요'});root.append(list,urlLabel,kind);
  add('이 위치에 하루 기록 저장',async()=>showStatus(await notionCall({op:'target',id:url.value,kind:kind.value})));
  add('이 위치를 AI 참고 자료로',async()=>showStatus(await notionCall({op:'reference',id:url.value,kind:kind.value})));
  add('참고 자료 불러오기',async()=>{if(!config?.reference)throw Error('참고 위치를 먼저 선택해 주세요');const result=await notionCall({op:'read',id:config.reference.id,kind:config.reference.kind});preview.textContent=result.text});
  add('내보낼 기록 미리보기',async()=>{preview.textContent=(await notionCall({op:'preview'})).markdown});root.append(preview);
  const label=document.createElement('label');label.className='form-label';label.textContent='일기 · AI 초안은 확인하고 수정하세요';root.append(label,draft);
  add('PC 로컬 AI로 초안 작성',async()=>{const result=await notionCall({op:'draft'});draft.value=result.draft;persist(notionDraftKey(),draft.value);toast('초안을 확인한 뒤 노션에 저장하세요')});
  add('기록과 일기를 노션에 저장',async()=>{const result=await notionCall({op:'publish',text:draft.value});state.textContent='저장 완료 · '+result.date+' 기상일\n'+result.url});
  add('저장한 일기 불러오기',async()=>{const result=await notionCall({op:'daily'});preview.textContent=result.page.text;draft.value=result.draft;persist(notionDraftKey(),draft.value);toast('노션 내용을 불러왔습니다. 실제 행동 기록은 유지됩니다')});
  run(async()=>showStatus(await notionCall({op:'status'})));
 })
}
function updateSheet(){native?.checkUpdates?.();showSheet('앱 업데이트',root=>{
 const note=document.createElement('p');note.className='form-note';root.append(note);
 const paint=()=>{if(!native?.updateStatus){note.textContent='Android 1.6을 한 번 설치하면 이후 PC 연결로 화면 업데이트를 받을 수 있습니다. APK 변경은 앱 안에서 설치를 요청합니다.';return}try{const s=JSON.parse(native.updateStatus());note.textContent='사용 중인 화면 2026102102\n설치 버전 '+s.installedName+' · PC 버전 '+s.availableName+'\n'+(s.uiReady?'새 화면 준비됨 · 화면 다시 열기를 누르세요':s.busy?'업데이트 확인·다운로드 중':'화면 업데이트는 PC 연결 시 자동으로 준비됩니다')+(s.error?'\n'+s.error:'')}catch{note.textContent='업데이트 상태를 읽지 못했습니다'}};
 paint();root.append(button('PC에서 업데이트 확인',()=>{native?.checkUpdates?.();paint()},'wide secondary'),button('준비된 화면 다시 열기',()=>{if(A.busy||A.gesture||A.conflict){toast('입력 또는 충돌 확인을 먼저 마쳐 주세요');return}native?.reloadUi?.()},'wide secondary'),button('새 APK 설치',()=>{native?.installUpdate?.();paint()},'wide secondary'));
 const timer=setInterval(()=>{if($('sheet').hidden||$('sheetTitle').textContent!=='앱 업데이트'){clearInterval(timer);return}paint()},1000);
})}

async function pairPc(address,code){if(A.busy)throw Error('앞선 입력이 저장된 뒤 연결해 주세요');const server=validServer(address);const result=await request('/api/pair','POST',{code},false,server);if((A.outbox.length||R?.pending())&&A.token&&result.token!==A.token)throw Error('저장 대기 중인 기록이 있습니다. 기존 PC와 동기화한 뒤 다른 PC에 연결해 주세요');const different=A.token&&A.token!==result.token;A.server=server;A.token=result.token;persist('ara.server',server);persist('ara.token',A.token);if(different){if(R)R.switchWorkspace();A.selection=null;A.view=null;A.lastId='';persist('ara.lastId','')}configureNotifications();if(!A.view&&!A.outbox.length&&result.date)changeDate(result.date);A.conflict=false;A.syncIssue=null;closeSheet();toast('PC와 연결했습니다');await refresh();flush()}
function scanQr(){if(!native?.scanQr){toast('앱 안의 카메라 연결은 Android 1.7 업데이트 후 사용할 수 있습니다');updateSheet();return}if(A.busy||A.outbox.length){toast('저장 대기 중인 입력을 먼저 동기화해 주세요');return}native.scanQr()}
async function acceptQr(payload){try{if(!payload||typeof payload.pc!=='string'||!/^\d{8}$/.test(payload.code||''))throw Error('PC의 연결용 QR을 다시 스캔해 주세요');await pairPc(payload.pc,payload.code)}catch(e){showSheet('QR 연결 확인',root=>{const note=document.createElement('p');note.className='conflict';note.textContent=e.message;root.append(note,button('다시 QR 스캔',scanQr),button('주소·코드 직접 입력',()=>connectionSheet(payload?.pc||''),'wide secondary'))})}}

function conflictBackupsSheet(){showSheet('보관한 충돌 기록',root=>{const backups=R.backups();const migrations=R.migrations?.()||[];if(!backups.length&&!migrations.length){const p=document.createElement('p');p.className='form-note';p.textContent='보관한 충돌 기록이 없습니다';root.append(p)}backups.forEach((backup,index)=>{const p=document.createElement('p');p.className='form-note';p.textContent=backup.date+' · '+new Date(backup.at).toLocaleString('ko-KR')+' · 휴대폰 기록 '+backup.phone.Days[0].Records.length+'개';root.append(p,button(backup.date+' 휴대폰 기록 복원',()=>R.restore(index),'wide secondary'))});for(const item of migrations){const note=document.createElement('p');note.className='form-note';note.textContent=item.date+' · 이전 버전 입력 '+item.pending.length+'개 원본 보관 · 반영 '+item.applied.length+'개 · 미반영 '+item.remaining.length+'개';root.append(note,button('이전 입력 보관 내용 보기',()=>showSheet('이전 버전 보관 원본',body=>{const p=document.createElement('p');p.className='form-note';p.textContent='현재 기록은 PC 없이 계속 입력할 수 있습니다. 미반영 입력은 자동 재전송하지 않습니다.'+(item.error?'\n'+item.error:'');const pre=document.createElement('pre');pre.className='notion-preview';pre.textContent=JSON.stringify(item,null,2);body.append(p,pre)}),'wide secondary'))}})}
function tasksSheet(){if(!R)return;showSheet('과제 체크리스트',root=>{for(const task of R.state().Tasks){const row=document.createElement('label');row.className='task-row';const check=document.createElement('input');check.type='checkbox';check.checked=task.DoneDates.includes(A.date);check.onchange=()=>R.task(task.Id,check.checked);row.append(check,document.createTextNode(task.Text));root.append(row)}const[label,text]=input('새 과제');text.maxLength=250;root.append(label,button('과제 추가',()=>{if(!text.value.trim())return;R.task('',text.value);tasksSheet()},'wide secondary'))})}
function satisfactionSettingsSheet(){if(!E||!R){toast('화면 업데이트 후 사용해 주세요');return}showSheet('빈칸 만족도 · 집계 설정',root=>{const state=R.state(),note=document.createElement('p');note.className='form-note';note.textContent='기상부터 현재까지만 집계합니다. 지난 날은 수면 예상까지 계산합니다. 기록한 칸의 점수는 바꾸지 않습니다.';root.append(note);const options=document.createElement('div');options.className='settings-options';const choose=(value,exclude)=>{if(R.edit({op:'satisfaction-settings',satisfaction:value,hidden:exclude}))satisfactionSettingsSheet()};for(let n=0;n<=5;n++){const b=button(String(n),()=>choose(n,false),'secondary');b.setAttribute('aria-pressed',String(!state.ExcludeBlankSatisfaction&&(state.BlankSatisfactionValue??2)===n));options.append(b)}const exclude=button('빈칸 제외',()=>choose(state.BlankSatisfactionValue??2,true),'wide secondary');exclude.setAttribute('aria-pressed',String(!!state.ExcludeBlankSatisfaction));root.append(options,exclude)})}
function settingsSheet(){showSheet('설정',root=>{const group=(name,build)=>{const section=document.createElement('section');section.className='settings-group';const h=document.createElement('h3');h.textContent=name;section.append(h);build(section);root.append(section)};const link=(label,fn)=>button(label,fn,'wide secondary settings-link');
 group('기록 설정',s=>{s.append(link('카테고리 관리',categorySettingsSheet),link('빈칸 만족도 · 집계 설정',satisfactionSettingsSheet));if(E)s.append(link('과제 체크리스트',tasksSheet))});
 group('연결·저장',s=>{const note=document.createElement('p');note.className='settings-status';note.textContent=$('syncnote').textContent;s.append(note,link('노션 연결 · 저장 위치',notionHubSheet),link('PC 연결 · QR',()=>connectionSheet()));if(E&&R?.issue)s.append(link('양쪽 변경 확인',()=>R.resolve()));if(A.conflict)s.append(link('저장 대기 입력 확인',syncIssueSheet))});
 group('앱 설정',s=>{const theme=link(A.dark?'☀ 라이트 모드':'☾ 다크 모드',()=>{toggleDarkMode();settingsSheet()});theme.setAttribute('aria-pressed',String(A.dark));s.append(theme,link('푸시 알림 · 권한 설정',notificationSheet),link('앱 업데이트',updateSheet));const h=document.createElement('label');h.className='form-label';const check=document.createElement('input');check.type='checkbox';check.checked=A.haptic;check.onchange=()=>{A.haptic=check.checked;persist('ara.haptic',A.haptic);buzz()};h.append(check,document.createTextNode(' 선택할 때 가벼운 진동'));s.append(h)});
 group('고급·문제 해결',s=>{if(A.view?.adjustments?.length)s.append(link('자동 조정 내역',adjustmentSheet));if(E)s.append(link('보관한 충돌 기록',conflictBackupsSheet));s.append(link('알림 진단 기록',notificationSheet),link('기존 PC 노션 · AI',notionSheet))})})}
function connectionSheet(override=""){showSheet('PC와 연결',root=>{root.append(button('QR 코드로 연결하기',scanQr));const[a,address]=input('PC 주소','url',override||A.server);address.placeholder='192.168.0.2:8765';const[c,code]=input('PC에 표시된 연결 코드','text');code.inputMode='numeric';code.maxLength=8;code.placeholder='8자리 연결 코드';root.append(a,c);const note=document.createElement('p');note.className='form-note';note.textContent='PC의 「휴대폰 연결」 버튼에서 주소와 코드를 확인하세요. 같은 Wi-Fi에서 연결됩니다.';root.append(note);root.append(button('연결하기',async()=>{try{await pairPc(address.value,code.value)}catch(e){toast(e.message)}}));})}
window.AraMobile={acceptQr,openConnection:connectionSheet,resolveNative(id,payload){const entry=A.pendingNative.get(id);if(!entry)return;A.pendingNative.delete(id);clearTimeout(entry.timeout);entry.resolve(payload)},back(){if(!$('blockMenu').hidden){closeContext();return true}if(!$('sheet').hidden){closeSheet();return true}if(A.selection){A.selection=null;paintSelection();return true}return false},state:()=>A};
async function request(path,method='GET',body=null,auth=true,server=A.server){if(!server)throw Error('PC 주소를 입력해 주세요');let response;if(native?.request){const id=uuid();response=await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>{A.pendingNative.delete(id);reject(Error('PC 연결을 기다리고 있습니다'))},path.startsWith('/api/notion')?140000:9000);A.pendingNative.set(id,{resolve,timeout});native.request(id,server+path,method,auth?A.token:'',body?JSON.stringify(body):'')})}else{const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),path.startsWith('/api/notion')?140000:6500);try{const r=await fetch(server+path,{method,headers:{...(auth?{Authorization:'Bearer '+A.token}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):null,signal:controller.signal,cache:'no-store'});response={status:r.status,body:await r.text()}}finally{clearTimeout(timer)}}let value;try{value=JSON.parse(response.body)}catch{throw Error('PC의 응답을 확인하지 못했습니다')}if(response.status<200||response.status>=300){const e=Error(value.error||'PC와 연결하지 못했습니다');e.status=response.status;throw e}return value}
function receive(view){persist('ara.cache.'+view.date,view);if(view.date!==A.date)return;const changed=A.view?.revision!==view.revision;A.view=view;if(changed&&!A.gesture)render();else status()}
async function refresh(){if(E&&R){await R.sync();return}if(!A.token||!A.server||A.busy)return;try{const view=await request('/api/day?date='+A.date);A.online=true;receive(view);native?.refreshNotifications?.();flush()}catch(e){A.online=false;status()}}
function enqueue(extra){if(E&&R)return R.edit(extra);if(A.conflict){syncIssueSheet();return false}if(!A.view||(!A.selection&&!['undo','category-save'].includes(extra.op)))return false;const sel=A.selection||{lane:1,first:0,last:0};const command={...sel,date:A.date,baseRevision:['category-save','undo'].includes(extra.op)?A.view.revision:sel.revision||A.view.revision,requestId:uuid(),...extra};A.outbox.push(command);persist('ara.outbox',A.outbox);render();buzz();flush();return true}
function syncIssueSheet(){
 const issue=A.syncIssue;if(!issue)return;
 const {command}=issue,invalid=issue.status===422;
 showSheet(invalid?'이동·입력 취소 필요':'변경된 기록 확인',root=>{
  const text=document.createElement('p');text.className='conflict';text.textContent=issue.message;root.append(text);
  const note=document.createElement('p');note.className='form-note';note.textContent=invalid?'이 입력은 적용되지 않았습니다. 취소하면 저장된 기록으로 돌아가 다시 선택할 수 있습니다.':'최신 기록을 확인한 뒤 이 입력을 다시 적용하거나 취소할 수 있습니다.';root.append(note);
  if(!invalid)root.append(button('최신 기록에 다시 적용',async()=>{if(A.busy)return;A.busy=true;try{const current=await request('/api/day?date='+command.date);receive(current);if(A.date===command.date&&A.selection)A.selection.revision=current.revision;command.baseRevision=current.revision;command.requestId=uuid();persist('ara.outbox',A.outbox);A.conflict=false;A.syncIssue=null;closeSheet()}catch(err){toast(err.message)}finally{A.busy=false;status()}if(!A.conflict)flush()}));
  root.append(button('이 대기 입력 취소 · 기록으로 돌아가기',async()=>{if(A.busy)return;A.busy=true;try{const current=await request('/api/day?date='+command.date);const index=A.outbox.indexOf(command);if(index>=0)A.outbox.splice(index,1);persist('ara.outbox',A.outbox);A.selection=null;A.conflict=false;A.syncIssue=null;A.online=true;receive(current);closeSheet();render()}catch(err){toast('연결 후 다시 취소해 주세요 · '+err.message)}finally{A.busy=false;status()}if(!A.conflict)flush()},'wide secondary'));
 })
}
function moveBlocked(view,lane,source,first){
 const list=lane?view.actual:view.planned;
 const meal=source.mealId||source.prepFor;
 const group=list.filter(b=>b.id===source.id||lane===0&&meal&&(b.mealId===meal||b.prepFor===meal));
 const shift=first-source.start;
 return group.some(b=>{const start=b.start+shift,end=start+b.count;return start<0||end>288||list.some(other=>!group.includes(other)&&other.start<end&&other.start+other.count>start)})
}
async function flush(){if(E&&R){await R.sync();return}if(A.busy||A.conflict||!A.token||!A.outbox.length)return;A.busy=true;try{while(A.outbox.length){const command=A.outbox[0];let view;try{view=await request('/api/command','POST',command)}catch(e){if(e.status===409||e.status===422){A.conflict=true;A.syncIssue={status:e.status,message:e.message,command};render();syncIssueSheet()}else{A.online=false;if(e.status===401)toast('PC 연결 코드를 다시 입력해 주세요')}throw e}A.online=true;const previous=command.baseRevision;if(A.selection?.revision===previous)A.selection.revision=view.revision;A.outbox.shift();for(const pending of A.outbox)if(pending.date===view.date&&pending.baseRevision===previous)pending.baseRevision=view.revision;persist('ara.outbox',A.outbox);if(command.op==='undo')A.selection=null;A.lastId=command.op==='undo'?'':command.requestId;persist('ara.lastId',A.lastId);A.lastDate=view.date;persist('ara.lastDate',A.lastDate);receive(view);native?.refreshNotifications?.();render()}}catch{}finally{A.busy=false;status()}}
