function resizeEdge(target,tile,lane,index,block,x){const handle=target.closest('.resize-handle');if(handle)return handle.dataset.edge;if(!block||block.category==='기상'||A.outbox.length)return null;const rect=tile.getBoundingClientRect();if(index===block.start&&x<=rect.left+16)return 'start';if(index===block.start+block.count-1&&x>=rect.right-16)return 'end';return null}
function holdContext(){const g=A.gesture;if(!g||g.resize||!$('sheet').hidden)return;if(!g.active)activate(g.id);if(!g.moved&&g.previous&&g.previous.lane===g.lane&&g.index>=g.previous.first&&g.index<=g.previous.last){A.selection={...g.previous};paintSelection()}if(scrollFrame)cancelAnimationFrame(scrollFrame);scrollFrame=null;g.longPressed=true;g.menuOpened=true;g.menuX=g.lastX;g.menuY=g.lastY;contextMenu('auto',{x:g.lastX,y:g.lastY,target:document.elementFromPoint(g.lastX,g.lastY)});buzz()}
