function endGesture(e){const g=A.gesture;if(!g||e.pointerId!==g.id)return;clearTimeout(pressTimer);if(scrollFrame)cancelAnimationFrame(scrollFrame);scrollFrame=null;$('timeline').querySelectorAll('.pressed').forEach(x=>x.classList.remove('pressed'));A.gesture=null;try{$('timeline').releasePointerCapture(e.pointerId)}catch{}$('resizeHint').hidden=true;if(g.menuOpened)return;if(g.resize){if(g.moved){if(A.outbox.length){toast('앞선 입력이 저장된 뒤 조절해 주세요');render();return}enqueue({op:'resize',id:g.block.id,baseRevision:g.revision})}else{paintSelection();if(g.lane===1&&g.block)contextMenu('score',{x:e.clientX,y:e.clientY,target:e.target})}return}if(g.active&&g.moved&&g.block&&!A.range){if(!g.copy&&A.outbox.length){toast("대기 입력이 저장된 뒤 블록을 옮겨 주세요");select(g.lane,g.block.start,g.block.start+g.block.count-1,g.revision);render();return}if(g.copy)enqueue({op:'copy',sourceId:g.block.id,baseRevision:g.revision});else if(A.selection.first!==g.block.start){if(moveBlocked(A.view,g.lane,g.block,A.selection.first)){toast('이동할 위치에 다른 활동이 있습니다. 빈 칸으로 옮기거나 먼저 범위를 수정해 주세요.');select(g.lane,g.block.start,g.block.start+g.block.count-1,g.revision);render()}else enqueue({op:'move',id:g.block.id,baseRevision:g.revision})};return}if(g.active&&g.moved)return;const previous=g.previous;const selected=previous&&previous.lane===g.lane&&g.index>=previous.first&&g.index<=previous.last;if(selected){A.selection=previous;paintSelection();contextMenu('auto',{x:e.clientX,y:e.clientY,target:e.target})}else if(g.block&&!A.range)select(g.lane,g.block.start,g.block.start+g.block.count-1,g.revision);else select(g.lane,g.index,g.index,g.revision);if(g.longPressed||g.lane===1&&g.block)contextMenu('auto',{x:e.clientX,y:e.clientY,target:e.target});buzz()}
